## Node.js：chalk 与 cli-table3

```typescript
import chalk from 'chalk';

function printBuildReport(): void {
  console.log(chalk.cyan.bold('=== 构建报告 ==='));
  console.log();
  console.log(chalk.green('✓') + ' 编译通过');
  console.log(chalk.green('✓') + ' 测试通过 (42/42)');
  console.log(chalk.yellow('⚠') + ' lint 发现 3 个警告');
  console.log();
  console.log(chalk.blue.bold('摘要') + ': 总耗时 ' + chalk.yellow('12.3s'));
}

printBuildReport();
```

